                "medical_disclaimer_desc": "PneumaScan একটি AI-চালিত সহায়ক সরঞ্জাম এবং এটি পেশাদার চিকিৎসা পরামর্শ, নিদান বা চিকিৎসার বিকল্প নয়। এই অ্যাপ্লিকেশনের দ্বারা প্রদত্ত ফলাফলগুলি সর্বদা একজন যোগ্য স্বাস্থ্যসেবা পেশাদার দ্বারা যাচাই করা উচিত। এই অ্যাপ্লিকেশনে আপনি যা পড়েছেন তার জন্য পেশাদার চিকিৎসা পরামর্শ উপেক্ষা করবেন না বা তা গ্রহণে বিলম্ব করবেন না।",
