                "privacy_desc": "আমরা আপনার গোপনীয়তাকে গুরুত্ব সহকারে নিই। PneumaScan দ্বারা প্রক্রিয়াকৃত সমস্ত মেডিকেল ইমেজ রিয়েল-টাইমে বিশ্লেষণ করা হয় এবং নিরাপদে প্রক্রিয়াকরণ করা হয়। আমরা স্পষ্ট সম্মতি ছাড়াই আমাদের পাবলিক সার্ভারে স্থায়ীভাবে ব্যক্তিগতভাবে শনাক্তযোগ্য রোগীর তথ্য (PII) সংরক্ষণ করি না। মডেলের সঠিকতা উন্নতির জন্য আনোনিমাইজড ডেটা ব্যবহার করা হতে পারে।",
