                "segment_title": "বৈশিষ্ট্য বিভাজন",
                "segment_prompt": "ফুসফুসের ক্ষেত্রগুলিকে বিভাজন করুন এবং কার্ডিয়াক সিলুয়েট এবং ডায়াফ্রাম বাদ দিন। টেক্সচারগত অসংগতি সহ আগ্রহের অঞ্চলগুলি (ROI) শনাক্ত করুন।",
                "severity_title": "তীব্রতা মূল্যায়ন",
                "severity_prompt": "ফুসফুসের প্রভাবিত এলাকার শতাংশ গণনা করুন। অস্বচ্ছতা বিতরণের ভিত্তিতে তীব্রতাকে মৃদু, মাঝারি বা গুরুতর হিসাবে শ্রেণীবদ্ধ করুন।",
                "why_matter": "কেন এই প্রম্পটগুলি গুরুত্বপূর্ণ?",
                "xai_title": "ব্যাখ্যামূলক AI (XAI)",
                "xai_desc": "হেলথকেয়ারে কেবল একটি \"ব্ল্যাক বক্স\" পূর্বাভাস যথেষ্ট নয়। আমাদের AI যে প্রম্পটগুলি \"চিন্তা\" করার জন্য ব্যবহার করে তা স্ট্যান্ডার্ডাইজ করার মাধ্যমে, আমরা যাচাই করতে পারি যে মডেলটি সঠিক শারীরবৃত্তীয় বৈশিষ্ট্যগুলি দেখছে, কোনো আর্টিফ্যাক্ট নয়।",
                "standard_title": "স্ট্যান্ডার্ডাইজেশন",
                "standard_desc": "নির্দিষ্ট প্রম্পটগুলি বিভিন্ন মেশিন এবং রোগীর ডেমোগ্রাফিক জুড়ে সামঞ্জস্যপূর্ণ বিশ্লেষণ নিশ্চিত করে, পক্ষপাত হ্রাস করে এবং ডায়াগনস্টিক সহায়তা টুলের নির্ভরযোগ্যতা উন্নত করে।"
