                "medical_disclaimer_desc": "PneumaScan என்பது ஒரு AI-அடிப்படையிலான உதவி கருவியாகும், இது தொழில்முறை மருத்துவ ஆலோசனை, நோயறிதல் அல்லது சிகிச்சைக்கு மாற்றாகாது. இந்த பயன்பாடு வழங்கும் முடிவுகள் எப்போதும் தகுதியான சுகாதார நிபுணரால் சரிபார்க்கப்பட வேண்டும். இந்த பயன்பாட்டில் நீங்கள் படித்தவற்றின் காரணமாக தொழில்முறை மருத்துவ ஆலோசனையைப் புறக்கணிக்காதீர்கள் அல்லது அதைப் பெறத் தாமதிக்காதீர்கள்.",
