                "privacy_desc": "உங்கள் தனியுரிமையை நாங்கள் மதிக்கிறோம். PneumaScan மூலம் செயலாக்கப்படும் அனைத்து மருத்துவப் படங்களும் நிகழ்நேரத்தில் பகுப்பாய்வு செய்யப்பட்டு பாதுகாப்பாக செயலாக்கப்படுகின்றன. முறையான ஒப்புதல் இல்லாமல் நோயாளியின் தனிப்பட்ட தகவல்களை (PII) நாங்கள் எங்கள் சேவையகங்களில் நிரந்தரமாகச் சேமிப்பதில்லை. மாதிரி துல்லியத்தை மேம்படுத்த பெயர் தெரியாத தரவு பயன்படுத்தப்படலாம்.",
