                "title_end": "& நுண்ணறிவுகள்",
                "subtitle": "எங்கள் AI மாதிரிகள் மருத்துவத் தரவை எவ்வாறு விளக்குகின்றன என்பதை ஆராயுங்கள். இந்த தூண்டுதல்கள் எங்கள் விளக்கக்கூடிய AI (XAI) இயந்திரத்தின் பின்னால் உள்ள தர்க்கரீதியான காரணத்தைக் காட்டுகின்றன.",
