                "segment_title": "அம்சம் பிரித்தல்",
                "segment_prompt": "நுரையீரல் மண்டலங்களைப் பிரித்து, இதய நிழல் மற்றும் உதரவிதானத்தைத் தவிர்க்கவும். அமைப்பு முரண்பாடுகள் உள்ள பகுதிகளை (ROI) அடையாளம் காணவும்.",
                "severity_title": "தீவிர மதிப்பீடு",
