                "subtitle": "AI-ನೆರವಿನ ನ್ಯುಮೋನಿಯಾ ಪತ್ತೆಗಾಗಿ PneumaScan ಬಳಸುವ ಮೊದಲು ದಯವಿಟ್ಟು ಈ ನಿಯಮಗಳನ್ನು ಎಚ್ಚರಿಕೆಯಿಂದ ಓದಿ.",
                "medical_disclaimer_title": "ವೈದ್ಯಕೀಯ ಹಕ್ಕುತ್ಯಾಗ",
                "medical_disclaimer_desc": "PneumaScan ಎನ್ನುವುದು AI ಆಧಾರಿತ ಸಹಾಯ ಸಾಧನವಾಗಿದೆ ಮತ್ತು ಇದು ವೃತ್ತಿಪರ ವೈದ್ಯಕೀಯ ಸಲಹೆ, ರೋಗನಿರ್ಣಯ ಅಥವಾ ಚಿಕಿತ್ಸೆಗೆ ಪರ್ಯಾಯವಲ್ಲ. ಈ ಅಪ್ಲಿಕೇಶನ್ ಒದಗಿಸಿದ ಫಲಿತಾಂಶಗಳನ್ನು ಯಾವಾಗಲೂ ಅರ್ಹ ಆರೋಗ್ಯ ವೃತ್ತಿಪರರು ಪರಿಶೀಲಿಸಬೇಕು. ಈ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿ ನೀವು ಓದಿರುವ ಯಾವುದೋ ಕಾರಣಕ್ಕಾಗಿ ವೃತ್ತಿಪರ ವೈದ್ಯಕೀಯ ಸಲಹೆಯನ್ನು ನಿರ್ಲಕ್ಷಿಸಬೇಡಿ ಅಥವಾ ಅದನ್ನು ಪಡೆಯಲು ವಿಳಂಬ ಮಾಡಬೇಡಿ.",
