                "privacy_desc": "ನಾವು ನಿಮ್ಮ ಗೌಪ್ಯತೆಯನ್ನು ಗೌರವಿಸುತ್ತೇವೆ. PneumaScan ಮೂಲಕ ಸಂಸ್ಕರಿಸಲಾದ ಎಲ್ಲಾ ವೈದ್ಯಕೀಯ ಚಿತ್ರಗಳನ್ನು ನೈಜ ಸಮಯದಲ್ಲಿ ವಿಶ್ಲೇಷಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಸುರಕ್ಷಿತವಾಗಿ ಸಂಸ್ಕರಿಸಲಾಗುತ್ತದೆ. ಸ್ಪಷ್ಟ ಒಮ್ಮತವಿಲ್ಲದೆ ನಾವು ರೋಗಿಯ ವೈಯಕ್ತಿಕ ಗುರುತಿಸಬಹುದಾದ ಮಾಹಿತಿಯನ್ನು (PII) ನಮ್ಮ ಸರ್ವರ್‌ಗಳಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ. ಮಾದರಿಯ ನಿಖರತೆಯನ್ನು ಸುಧಾರಿಸಲು ಅನಾಮಧೇಯ ಡೇಟಾವನ್ನು ಬಳಸಬಹುದು.",
                "usage_title": "ಬಳಕೆಯ ಮಾರ್ಗಸೂಚಿಗಳು",
                "usage_1": "ನೀವು ಈ ಸೇವೆಯನ್ನು ಕಾನೂನುಬದ್ಧ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಮತ್ತು ಈ ನಿಯಮಗಳ ಪ್ರಕಾರ ಮಾತ್ರ ಬಳಸಲು ಒಪ್ಪುತ್ತೀರಿ.",
                "usage_2": "ನೀವು ಯಾವುದೇ ದುರುದ್ದೇಶಪೂರಿತ ಸಾಫ್ಟ್‌ವೇರ್ ಅನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಲು ಅಥವಾ ಅಪ್ಲಿಕೇಶನ್‌ನ ಭದ್ರತೆಯನ್ನು ರಾಜಿ ಮಾಡಲು ಪ್ರಯತ್ನಿಸಬಾರದು.",
                "usage_3": "ವೈದ್ಯಕೀಯ ಚಿತ್ರಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಲು ಅಗತ್ಯವಾದ ಹಕ್ಕುಗಳು ಮತ್ತು ಒಮ್ಮತವನ್ನು ಹೊಂದಿರುವುದನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುವುದು ಬಳಕೆದಾರರ ಜವಾಬ್ಯಾರಿಯಾಗಿದೆ.",
